import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { MapPin, Share2 } from "lucide-react";

import {
  Screen,
  PrimaryButton,
  EmptyState,
} from "../components/common/UI";

import "../styles/Basket.css";

export default function Basket() {
  const navigate = useNavigate();
  const [basket, setBasket] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /baskets
    setBasket({
      _id: "1",
      public_id: "BK-1234",
      basket_name: "Weekly groceries",
      status: "open",
      merchant: {
        _id: "1",
        business_name: "SupaMart Grocers"
      },
      items: [
        {
          product_id: "1",
          name: "Fresh Milk (500ml)",
          unit_label: "500ml bottle",
          product_image: "https://images.unsplash.com/photo-1563636619-e9143da7973b?w=700",
          quantity: 2,
          unit_price: { kes: "57.00", aud: "0.63" },
          line_total: { kes: "114.00", aud: "1.26" },
          in_stock: true
        },
        {
          product_id: "2",
          name: "Sourdough Artisanal Bread",
          unit_label: "1 loaf",
          product_image: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=700",
          quantity: 1,
          unit_price: { kes: "400.00", aud: "4.43" },
          line_total: { kes: "400.00", aud: "4.43" },
          in_stock: true
        }
      ],
      item_count: 3,
      subtotal: { kes: "514.00", aud: "5.69" },
      service_charge: { kes: "50.00", aud: "0.55" },
      total: { kes: "564.00", aud: "6.24" },
      fx_rate: "90.30"
    });
    setLoading(false);
  }, []);

  if (loading) {
    return <Screen title="My Basket">Loading...</Screen>;
  }

  if (!basket || basket.items.length === 0) {
    return (
      <Screen title="My Basket">
        <EmptyState
          icon="🧺"
          title="Your basket is empty"
          description="Explore products and add your favorites."
          action="Browse Merchants"
          onAction={() => navigate("/home")}
        />
      </Screen>
    );
  }

  const handleQuantityChange = (productId, newQuantity) => {
    // TODO: Implement API call to PATCH /baskets/:basketId/items/:productId
    if (newQuantity < 1) {
      // Remove item
      // DELETE /baskets/:basketId/items/:productId
    } else {
      // Update quantity
    }
  };

  const handleShare = () => {
    // TODO: Implement API call to POST /baskets/:basketId/share
  };

  return (
    <Screen title={basket.basket_name || "My Basket"}>
      <div className="basket-header">
        <div className="row">
          <MapPin size={14} />
          <span className="muted small">{basket.merchant.business_name}</span>
        </div>
        <button className="icon-btn" onClick={handleShare}>
          <Share2 size={18} />
        </button>
      </div>

      {basket.items.map((item) => (
        <div
          className="basket-line panel"
          key={item.product_id}
        >
          <img
            src={item.product_image}
            alt={item.name}
          />

          <div className="basket-line-info">
            <strong>{item.name}</strong>

            <small className="muted">
              {item.unit_label}
            </small>

            <b className="orange">
              KSh {item.line_total.kes}
              <span className="aud-price">≈ AUD {item.line_total.aud}</span>
            </b>
          </div>

          <div className="quantity-controls">
            <button
              onClick={() => handleQuantityChange(item.product_id, item.quantity - 1)}
              disabled={!item.in_stock}
            >
              −
            </button>

            <b>{item.quantity}</b>

            <button
              onClick={() => handleQuantityChange(item.product_id, item.quantity + 1)}
              disabled={!item.in_stock}
            >
              +
            </button>
          </div>
        </div>
      ))}

      <div className="panel">
        <h3 className="card-title">
          Order Summary
        </h3>

        <div className="summary-line">
          <span>Subtotal ({basket.item_count} items)</span>
          <span>KSh {basket.subtotal.kes}</span>
        </div>

        <div className="summary-line">
          <span>Service charge</span>
          <span>KSh {basket.service_charge.kes}</span>
        </div>

        <div className="divider" />

        <div className="summary-line">
          <strong>Total</strong>
          <strong className="orange">
            KSh {basket.total.kes}
            <span className="aud-price">≈ AUD {basket.total.aud}</span>
          </strong>
        </div>
      </div>

      <PrimaryButton
        onClick={() => navigate("/checkout")}
      >
        Proceed to Checkout
      </PrimaryButton>
    </Screen>
  );
}
